            return None
        elif ido == 99:
            if d['info'] != 0:
                return None
            break
        else:
            return None
    return p.extract(True)


class Solver:
    def solve(self, problem, **kwargs):
        A = problem["matrix"]
        k = problem["k"]
        N = A.shape[0]
        res = None
        try:
            if threadpool_limits is not None:
                with threadpool_limits(1):
                    res = _run(A, k)
            else:
                res = _run(A, k)
        except Exception:
            res = None
        if res is None:
            res = eigs(A, k=k, v0=np.ones(N, dtype=A.dtype), maxiter=N * 200,
                       ncv=max(2 * k + 1, 20))
        w, V = res
        pairs = list(zip(w, V.T))
        pairs.sort(key=lambda pair: -np.abs(pair[0]))
        return [pair[1] for pair in pairs]
