import numpy as np
def ell(indptr, indices, data, n, C):
    rl = np.diff(indptr)
    perm = np.argsort(-rl, kind='stable').astype(np.int32)
    npad = ((n + C - 1) // C) * C
    perm_p = np.concatenate([perm, np.full(npad - n, -1, np.int32)])
    rlp = np.where(perm_p >= 0, rl[np.maximum(perm_p, 0)], 0)
    nch = npad // C
    L = rlp.reshape(nch, C).max(axis=1).astype(np.int32)
    off = np.zeros(nch, np.int64)
    off[1:] = np.cumsum(L[:-1].astype(np.int64) * C)
    tot = int(L.sum()) * C
    idx = np.zeros(tot, np.int32); val = np.zeros(tot, np.float64)
    slots = np.arange(n); cnt = rl[perm]
    c = slots // C; r = slots % C
    rep = np.repeat(slots, cnt)
    starts = np.repeat(indptr[perm], cnt)
    kk = np.arange(rep.size) - np.repeat(np.cumsum(cnt) - cnt, cnt)
    src = starts + kk
    dst = off[c[rep]] + kk * C + r[rep]
    idx[dst] = indices[src]; val[dst] = data[src]
    return nch, L, off, idx, val, perm_p
